import heapq

def toposort(nodes, edges):
    adj = {n: set() for n in nodes}
    in_degree = {n: 0 for n in nodes}

    for u, v in edges:
        if u == v:
            raise ValueError("Cycle detected")
        if v not in adj[u]:
            adj[u].add(v)
            in_degree[v] += 1

    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(nodes):
        raise ValueError
